import { useMemo } from 'react';

import { featureToggles } from 'config/featureToggle';
import { useFeatureToggle } from 'hooks';
import { KpiEndpoints } from 'pages/pillars/ValueCreation/VolumePages/config/api';
import { KpiConfig } from 'pages/pillars/ValueCreation/VolumePages/config/kpiConfigs';
import {
  isBeerAdjProductScope,
  resolveAppliedProductScope,
} from 'pages/pillars/ValueCreation/VolumePages/config/productScope';
import {
  REPORT_TYPE,
  ReportType,
} from 'pages/pillars/ValueCreation/VolumePages/config/reportType';

type AppliedFilters = {
  product_scope?: unknown;
};

export interface VolumePagesKpiRouting {
  endpoints: KpiEndpoints;
  reporttype: ReportType;
}

export const useKpiEndpoint = (
  config: KpiConfig,
  applied?: AppliedFilters,
): VolumePagesKpiRouting => {
  const [isProductScopeEnabled] = useFeatureToggle(
    featureToggles.pillar.valueCreation.submenus.volumePages.filters
      .productScope,
  );
  const productScope = resolveAppliedProductScope(applied);

  return useMemo(() => {
    const shouldUseBeerAdjScope =
      isProductScopeEnabled &&
      Boolean(config.beerAdjEndpoints) &&
      isBeerAdjProductScope(productScope);

    return {
      endpoints:
        shouldUseBeerAdjScope && config.beerAdjEndpoints
          ? config.beerAdjEndpoints
          : config.endpoints,
      reporttype: shouldUseBeerAdjScope
        ? REPORT_TYPE.BEER_ADJ
        : REPORT_TYPE.TOTAL,
    };
  }, [
    config.beerAdjEndpoints,
    config.endpoints,
    isProductScopeEnabled,
    productScope,
  ]);
};
